void screenViewBase::handleTickEvent()
{
    frameCountInfoUpdate1Interval++;
    if(frameCountInfoUpdate1Interval == TICK_INFOUPDATE1_INTERVAL)
    {
        //InfoUpdate1
        //When every N tick call virtual function
        //Call InfoUpdate1
        InfoUpdate1();
        frameCountInfoUpdate1Interval = 0;
    }
}

void screenViewBase::handleKeyEvent(uint8_t key)
{
    if(21 == key)
    {
        //changeredmap
        //When hardware button 21 clicked change screen to redmap
        //Go to redmap with no screen transition
        application().gotoredmapScreenNoTransition();
    
    }

    if(23 == key)
    {
        //changebluemap
        //When hardware button 23 clicked change screen to bluemap
        //Go to bluemap with no screen transition
        application().gotobluemapScreenNoTransition();
    
    }
}
